# Lowercase index sets for fast case-insensitive lookup.
_FIRST_NAMES_LOWER: frozenset[str] = frozenset(n.lower() for n in FIRST_NAMES)
_SURNAMES_LOWER: frozenset[str] = frozenset(n.lower() for n in SURNAMES)
_LOCALITIES_LOWER: frozenset[str] = frozenset(l.lower() for l in LOCALITIES)


def is_first_name(token: str) -> bool:
    """Case-insensitive Polish first-name lookup."""
    return token.lower() in _FIRST_NAMES_LOWER


def is_surname(token: str) -> bool:
    """Case-insensitive Polish surname lookup."""
    return token.lower() in _SURNAMES_LOWER


def is_locality(token: str) -> bool:
    """Case-insensitive Polish locality (city/village) lookup.

    Matches both nominative ("Warszawa") and genitive ("Warszawy") forms.
    """
    return token.lower() in _LOCALITIES_LOWER


_SURNAME_SUFFIXES: tuple[str, ...] = (
    "ski", "ska", "cki", "cka", "dzki", "dzka",
    "wski", "wska", "owski", "owska", "ewski", "ewska",
    "iński", "ińska", "yński", "yńska",
    "ek", "ak", "uk", "yk", "ik", "ok",
    "wicz", "owicz", "ewicz", "icz",
    "acz",
    "ara", "ora", "ura",
)


def _looks_like_surname(token: str) -> bool:
    """Heuristic: does this token look like a Polish surname by suffix?"""
    t = token.lower()
    return any(t.endswith(s) for s in _SURNAME_SUFFIXES)


def could_be_person_name(first: str, last: str) -> bool:
    """Return True if `first` + `last` look like a real Polish person name.

    A pair qualifies when:
      * `first` is in the FIRST_NAMES gazetteer, AND
      * `last` is in the SURNAMES gazetteer OR ends with a typical
        Polish surname suffix (-ski/-ska/-wicz/-ak/...).
    """
    return is_first_name(first) and (is_surname(last) or _looks_like_surname(last))


